//! Cross-language conformance: stores the Go `madder` wrote
//! (`tests/fixtures/`, regenerated by `just codemod-rust-fixtures`) read
//! back byte-exact, and what this crate writes lands where Go would put it.

use std::collections::BTreeSet;
use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};

use madder_store::piggy_markl::FormatId;
use madder_store::{BlobId, Error, OpenOptions, Store, Unsealer, X25519Identity};

const FIXTURES: &[&str] = &["zstd-blake2b256", "none-sha256"];

fn fixture_dir(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name)
}

/// The fixture's X25519 identity: the seed is the secret scalar.
fn identity(dir: &Path) -> X25519Identity {
    let hex = fs::read_to_string(dir.join("x25519-secret.hex")).unwrap();
    let secret = hex::decode(hex.trim()).unwrap();
    let public =
        madder_store::age_x25519::public_key(secret.as_slice().try_into().unwrap()).to_vec();
    X25519Identity { public, secret }
}

fn expected_blobs(dir: &Path) -> Vec<(String, BlobId)> {
    fs::read_to_string(dir.join("blobs.tsv"))
        .unwrap()
        .lines()
        .map(|line| {
            let (name, id) = line.split_once('\t').unwrap();
            (name.to_owned(), BlobId::parse(id).unwrap())
        })
        .collect()
}

fn plaintext(dir: &Path, name: &str) -> Vec<u8> {
    fs::read(dir.join("plaintexts").join(name)).unwrap()
}

/// A writable copy of a fixture store, in a fresh temp dir.
fn scratch_copy(name: &str) -> (tempdir::Dir, PathBuf) {
    let scratch = tempdir::Dir::new();
    let store = scratch.path().join("store");
    copy_tree(&fixture_dir(name).join("store"), &store);
    (scratch, store)
}

fn copy_tree(from: &Path, to: &Path) {
    fs::create_dir_all(to).unwrap();
    for entry in fs::read_dir(from).unwrap() {
        let entry = entry.unwrap();
        let target = to.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            copy_tree(&entry.path(), &target);
        } else {
            fs::copy(entry.path(), &target).unwrap();
        }
    }
}

/// A minimal temp dir that removes itself, so the tests need no extra
/// dependency.
mod tempdir {
    use std::path::{Path, PathBuf};

    pub struct Dir(PathBuf);

    impl Dir {
        pub fn new() -> Dir {
            let unique = format!(
                "madder-store-test-{}-{}",
                std::process::id(),
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap()
                    .as_nanos()
            );
            let path = std::env::temp_dir().join(unique);
            std::fs::create_dir_all(&path).unwrap();
            Dir(path)
        }

        pub fn path(&self) -> &Path {
            &self.0
        }
    }

    impl Drop for Dir {
        fn drop(&mut self) {
            // Blobs are published read-only; the directory is still ours.
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }
}

#[test]
fn opens_each_fixture_and_reports_its_sealed_recipients_without_a_key() {
    for name in FIXTURES {
        let dir = fixture_dir(name);
        let store = Store::open(dir.join("store")).unwrap();

        assert!(!store.is_unsealed());
        assert!(
            store
                .public_key()
                .to_wire()
                .starts_with("piggy-recipient-v1@age_x25519_pub-")
        );

        let recipients = store.sealed_recipients();
        let piggy_ids = fs::read_to_string(dir.join("piggy-ids")).unwrap();
        let lines: Vec<&str> = piggy_ids.lines().collect();
        assert_eq!(recipients.len(), 2, "{name}");
        assert_eq!(recipients[0].to_wire(), lines[0]);
        assert_eq!(recipients[1].to_wire(), lines[1]);
        assert_eq!(recipients[0].format(), FormatId::AgeX25519Pub);
        assert_eq!(recipients[1].format(), FormatId::PivyEcdhP256Pub);

        let source = store.recipient_source();
        assert_eq!(source.kind, "embedded");
        assert_eq!(source.locator, None);
        assert_eq!(source.pigpen.as_deref(), Some(piggy_ids.as_str()));
    }
}

#[test]
fn has_and_ids_need_no_key() {
    for name in FIXTURES {
        let dir = fixture_dir(name);
        let store = Store::open(dir.join("store")).unwrap();
        let expected = expected_blobs(&dir);

        for (_, id) in &expected {
            assert!(store.has(id), "{name}: has({id})");
        }
        let null = store.config().hash_format.null_id();
        assert!(store.has(&null), "{name}: the null id is always present");

        let listed: BTreeSet<String> = store.ids().unwrap().iter().map(|id| id.to_wire()).collect();
        let wanted: BTreeSet<String> = expected.iter().map(|(_, id)| id.to_wire()).collect();
        assert_eq!(listed, wanted, "{name}: ids()");
    }
}

#[test]
fn reading_before_unseal_is_locked_except_for_the_null_blob() {
    let dir = fixture_dir(FIXTURES[0]);
    let store = Store::open(dir.join("store")).unwrap();
    let (_, id) = &expected_blobs(&dir)[0];
    assert!(matches!(store.read(id), Err(Error::Locked)));

    let null = store.config().hash_format.null_id();
    assert_eq!(store.read_to_vec(&null).unwrap(), b"");
}

#[test]
fn reads_every_go_written_blob_byte_exact() {
    for name in FIXTURES {
        let dir = fixture_dir(name);
        let store = Store::open(dir.join("store")).unwrap();
        let identities = [identity(&dir)];
        store
            .unseal(&Unsealer {
                oracle: None,
                identities: &identities,
            })
            .unwrap();
        assert!(store.is_unsealed());

        for (plain, id) in expected_blobs(&dir) {
            let got = store.read_to_vec(&id).unwrap();
            assert_eq!(got, plaintext(&dir, &plain), "{name}/{plain}");
        }

        // Streaming in small reads gives the same bytes.
        let (plain, id) = expected_blobs(&dir).pop().unwrap();
        let mut reader = store.read(&id).unwrap();
        let mut out = Vec::new();
        let mut buf = [0u8; 1000];
        loop {
            let n = reader.read(&mut buf).unwrap();
            if n == 0 {
                break;
            }
            out.extend_from_slice(&buf[..n]);
        }
        assert_eq!(out, plaintext(&dir, &plain), "{name}/{plain} streamed");
    }
}

#[test]
fn the_wrong_identity_does_not_unseal_and_a_missing_blob_is_not_found() {
    let dir = fixture_dir(FIXTURES[0]);
    let store = Store::open(dir.join("store")).unwrap();

    let wrong = X25519Identity {
        public: madder_store::age_x25519::public_key(&[9u8; 32]).to_vec(),
        secret: vec![9u8; 32],
    };
    let err = store
        .unseal(&Unsealer {
            oracle: None,
            identities: &[wrong],
        })
        .unwrap_err();
    assert!(matches!(err, Error::Pigpen(_)), "{err:?}");
    assert!(!store.is_unsealed());

    let identities = [identity(&dir)];
    store
        .unseal(&Unsealer {
            oracle: None,
            identities: &identities,
        })
        .unwrap();
    let mut digest = [0u8; 32];
    digest[0] = 0xab;
    let missing = BlobId::new(store.config().hash_format, digest);
    assert!(matches!(store.read(&missing), Err(Error::NotFound(_))));
}

#[test]
fn rewriting_a_fixture_plaintext_yields_the_same_id_and_path() {
    for name in FIXTURES {
        let dir = fixture_dir(name);
        let (_scratch, base) = scratch_copy(name);
        let store = Store::open(&base).unwrap();

        for (plain, id) in expected_blobs(&dir) {
            // The blob exists already: the write hits link(2)'s EEXIST and
            // is a no-op that returns the same id.
            let written = store.write_bytes(&plaintext(&dir, &plain)).unwrap();
            assert_eq!(written, id, "{name}/{plain}");
        }

        // Zero bytes: the null id, and no file anywhere.
        let null = store.write_bytes(b"").unwrap();
        assert!(null.is_null());
        assert_eq!(store.ids().unwrap().len(), expected_blobs(&dir).len());
    }
}

#[test]
fn a_new_blob_is_published_read_only_and_reads_back() {
    for name in FIXTURES {
        let dir = fixture_dir(name);
        let (_scratch, base) = scratch_copy(name);
        let store = Store::open(&base).unwrap();

        let content: Vec<u8> = (0..200_000u32).map(|i| (i * 7 % 256) as u8).collect();
        let id = store.write(&content[..]).unwrap();
        assert!(store.has(&id));

        let path =
            base.join(id.relative_path(&store.config().hash_buckets, store.config().multi_hash));
        assert!(path.is_file(), "{name}: {}", path.display());
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            assert_eq!(
                fs::metadata(&path).unwrap().permissions().mode() & 0o777,
                0o444
            );
        }
        assert!(
            fs::read(&path)
                .unwrap()
                .starts_with(b"age-encryption.org/v1\n")
        );

        // The temp dir is a sibling of the store, and holds nothing after.
        let temp_dir = base.parent().unwrap().join(".store.tmp");
        assert!(temp_dir.is_dir());
        assert_eq!(fs::read_dir(&temp_dir).unwrap().count(), 0);

        let identities = [identity(&dir)];
        store
            .unseal(&Unsealer {
                oracle: None,
                identities: &identities,
            })
            .unwrap();
        assert_eq!(store.read_to_vec(&id).unwrap(), content);

        let mut listed = store.ids().unwrap();
        listed.retain(|listed| *listed == id);
        assert_eq!(listed.len(), 1);
    }
}

#[test]
fn a_tampered_config_or_blob_is_refused() {
    let name = FIXTURES[0];
    let dir = fixture_dir(name);
    let (_scratch, base) = scratch_copy(name);

    // Config body.
    let config_path = base.join("blob_store-config");
    let mut config = fs::read(&config_path).unwrap();
    let at = config.windows(4).position(|w| w == b"zstd").unwrap();
    config[at..at + 4].copy_from_slice(b"none");
    fs::write(&config_path, &config).unwrap();
    assert!(matches!(Store::open(&base), Err(Error::ConfigTampered)));
    fs::copy(
        fixture_dir(name).join("store/blob_store-config"),
        &config_path,
    )
    .unwrap();

    // Blob bytes: the age layer catches it before any plaintext is seen.
    let store = Store::open(&base).unwrap();
    let identities = [identity(&dir)];
    store
        .unseal(&Unsealer {
            oracle: None,
            identities: &identities,
        })
        .unwrap();
    let (_, id) = expected_blobs(&dir).pop().unwrap();
    let path = base.join(id.relative_path(&store.config().hash_buckets, store.config().multi_hash));
    let mut bytes = fs::read(&path).unwrap();
    let last = bytes.len() - 1;
    bytes[last] ^= 1;
    {
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&path, fs::Permissions::from_mode(0o644)).unwrap();
        }
    }
    fs::write(&path, &bytes).unwrap();
    assert!(store.read_to_vec(&id).is_err());
}

#[test]
fn an_explicit_temp_dir_is_honoured() {
    let name = FIXTURES[1];
    let (scratch, base) = scratch_copy(name);
    let temp_dir = scratch.path().join("elsewhere");
    let store = Store::open_with(
        &base,
        OpenOptions {
            temp_dir: Some(temp_dir.clone()),
            ..OpenOptions::default()
        },
    )
    .unwrap();
    let id = store.write_bytes(b"temp dir test").unwrap();
    assert!(store.has(&id));
    assert!(temp_dir.is_dir());
    assert!(!base.parent().unwrap().join(".store.tmp").exists());
}
